import http.client
import json
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit


class LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for name in ("href", "src", "action"):
            value = attrs.get(name)
            if value:
                self.links.append({"tag": tag, "attribute": name, "value": value})


def request_once(url):
    parts = urlsplit(url)
    if parts.scheme not in ("http", "https") or not parts.hostname:
        raise ValueError("Unsupported or invalid redirect URL: " + url)

    port = parts.port
    if parts.scheme == "https":
        connection = http.client.HTTPSConnection(parts.hostname, port=port, timeout=10)
    else:
        connection = http.client.HTTPConnection(parts.hostname, port=port, timeout=10)

    path = parts.path or "/"
    if parts.query:
        path += "?" + parts.query
    try:
        connection.request(
            "GET",
            path,
            headers={
                "Host": parts.netloc,
                "User-Agent": "HTTP-baseline/1.0",
                "Accept": "*/*",
                "Connection": "close",
            },
        )
        response = connection.getresponse()
        body = response.read()
        return {
            "url": url,
            "status": response.status,
            "reason": response.reason,
            "headers": response.getheaders(),
            "body_bytes": len(body),
            "body": body.decode("utf-8", errors="replace"),
        }
    finally:
        connection.close()


def inspect_resource(initial_url):
    result = {"requested_url": initial_url, "responses": [], "error": None}
    current = initial_url
    for hop in range(11):
        try:
            response = request_once(current)
        except Exception as exc:
            result["error"] = {
                "url": current,
                "type": type(exc).__name__,
                "message": str(exc),
            }
            break

        result["responses"].append(response)
        location = next(
            (value for name, value in response["headers"] if name.lower() == "location"),
            None,
        )
        if response["status"] not in (301, 302, 303, 307, 308) or not location:
            break
        if hop == 10:
            result["error"] = {
                "url": current,
                "type": "RedirectLimit",
                "message": "Stopped after 10 redirect hops; further destination was not requested.",
            }
            break
        current = urljoin(current, location)

    for response in result["responses"]:
        content_type = next(
            (value for name, value in response["headers"] if name.lower() == "content-type"),
            "",
        )
        if "html" in content_type.lower() or "<html" in response["body"][:1000].lower():
            parser = LinkExtractor()
            try:
                parser.feed(response["body"])
                response["links"] = parser.links
            except Exception as exc:
                response["link_parse_error"] = {
                    "type": type(exc).__name__,
                    "message": str(exc),
                }
    return result


def main():
    base = "http://192.168.2.2:80"
    resources = ["/", "/robots.txt", "/sitemap.xml"]
    output = {
        "target": base,
        "method": "GET",
        "note": "Bodies are decoded as UTF-8 with replacement; body_bytes reports the received byte count. Redirect responses and destinations are recorded as separate hops.",
        "results": [inspect_resource(base + path) for path in resources],
    }
    print(json.dumps(output, ensure_ascii=False))


if __name__ == "__main__":
    main()

