import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

import framework_evidence

BASE = "http://192.168.2.2"
ORIGIN = ("http", "192.168.2.2", 80)


class ReferenceParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.refs = []

    def handle_starttag(self, tag, attrs):
        for name, value in attrs:
            if name.lower() in ("href", "src", "action") and value:
                self.refs.append(value.strip())

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def same_origin_url(reference, base_url):
    try:
        joined = urljoin(base_url, reference.strip())
        parts = urlsplit(joined)
        port = parts.port or (443 if parts.scheme == "https" else 80)
        if (parts.scheme.lower(), (parts.hostname or "").lower(), port) != ORIGIN:
            return None
        if parts.username is not None or parts.password is not None:
            return None
        # Fragments are client-side only and do not identify a distinct request.
        return urlunsplit(("http", "192.168.2.2", parts.path or "/", parts.query, ""))
    except (ValueError, AttributeError):
        return None


def find_stdout(value):
    if isinstance(value, dict):
        candidate = value.get("stdout")
        if isinstance(candidate, str):
            return candidate
        for child in value.values():
            found = find_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_stdout(child)
            if found is not None:
                return found
    return None


def response_parts(raw):
    """Extract the final HTTP status, headers and body from curl -i output."""
    if raw is None:
        return None, [], None
    text = raw.replace("\r\n", "\n")
    matches = list(re.finditer(r"(?m)^HTTP/\d(?:\.\d)?\s+\d{3}[^\n]*\n", text))
    if not matches:
        return None, [], text
    match = matches[-1]
    status_match = re.search(r"\s(\d{3})(?:\s|$)", match.group(0).strip())
    status = int(status_match.group(1)) if status_match else None
    remainder = text[match.end():]
    header_end = remainder.find("\n\n")
    if header_end < 0:
        return status, [], remainder
    headers = remainder[:header_end].splitlines()
    body = remainder[header_end + 2:]
    return status, headers, body


def references_in(url, body):
    refs = []
    parser = ReferenceParser()
    try:
        parser.feed(body)
        refs.extend(parser.refs)
    except Exception:
        pass

    # CSS imports and url(...) references can expose additional local resources.
    refs.extend(re.findall(r"(?is)@import\s+(?:url\()?\s*['\"]?([^\s'\")]+)", body))
    refs.extend(re.findall(r"(?is)url\(\s*['\"]?([^\s'\")]+)", body))

    # Sitemap entries and robots.txt sitemap/path directives.
    refs.extend(re.findall(r"(?is)<loc>\s*(.*?)\s*</loc>", body))
    for line in body.splitlines():
        stripped = line.strip()
        if stripped.lower().startswith("sitemap:"):
            refs.append(stripped.split(":", 1)[1].strip())
        elif stripped.lower().startswith(("allow:", "disallow:")):
            value = stripped.split(":", 1)[1].strip()
            if value and value != "/":
                refs.append(value)

    found = []
    for ref in refs:
        candidate = same_origin_url(ref, url)
        if candidate and candidate not in found:
            found.append(candidate)
    return found


def main():
    initial = [
        BASE + "/index.php?page=page1.php",
        BASE + "/index.php?page=page2.php",
        BASE + "/index.php?page=page3.php",
        BASE + "/css/style.css",
        BASE + "/robots.txt",
        BASE + "/sitemap.xml",
    ]
    queue = list(initial)
    seen = set()

    while queue:
        url = queue.pop(0)
        if url in seen:
            continue
        seen.add(url)
        argv = ["curl", "--silent", "--show-error", "--include", "--max-time", "15", url]
        try:
            envelope = framework_evidence.run_tool(argv)
            raw = find_stdout(envelope)
            status, headers, body = response_parts(raw)
            refs = references_in(url, body or "") if body is not None else []
            for ref in refs:
                if ref not in seen and ref not in queue:
                    queue.append(ref)
            record = {
                "requested_url": url,
                "tool_argv": argv,
                "raw_evidence_envelope": envelope,
                "parsed_status": status,
                "parsed_headers": headers,
                "response_content": body,
                "same_origin_references": refs,
            }
            print(json.dumps(record, ensure_ascii=False), flush=True)
        except Exception as exc:
            print(json.dumps({
                "requested_url": url,
                "tool_argv": argv,
                "error": "%s: %s" % (type(exc).__name__, exc),
                "coverage_note": "This request did not produce a usable response; other queued resources continue to be checked.",
            }, ensure_ascii=False), flush=True)


if __name__ == "__main__":
    main()

