import json
import re
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.2.2:80"
HOST = "192.168.2.2"
PORT = 80
MAX_BYTES = 1048576
TIMEOUT = 8

class RefParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.refs = []
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for key in ("href", "src", "action"):
            value = attrs.get(key)
            if value:
                self.refs.append(value)


def is_same_origin(url):
    p = urllib.parse.urlsplit(url)
    try:
        port = p.port or (443 if p.scheme == "https" else 80)
    except ValueError:
        return False
    return p.scheme in ("http", "https") and p.hostname == HOST and port == PORT


def request(url):
    req = urllib.request.Request(url, headers={"User-Agent": "resource-observation/1.0"})
    opener = urllib.request.build_opener(urllib.request.HTTPHandler(), urllib.request.HTTPSHandler())
    try:
        with opener.open(req, timeout=TIMEOUT) as resp:
            raw = resp.read(MAX_BYTES + 1)
            return {"status": resp.status, "headers": dict(resp.headers.items()),
                    "body": raw[:MAX_BYTES], "truncated": len(raw) > MAX_BYTES,
                    "final_url": resp.geturl(), "error": ""}
    except urllib.error.HTTPError as exc:
        try:
            raw = exc.read(MAX_BYTES + 1)
        except Exception:
            raw = b""
        return {"status": exc.code, "headers": dict(exc.headers.items()) if exc.headers else {},
                "body": raw[:MAX_BYTES], "truncated": len(raw) > MAX_BYTES,
                "final_url": exc.geturl(), "error": "HTTP response"}
    except Exception as exc:
        return {"status": None, "headers": {}, "body": b"", "truncated": False,
                "final_url": url, "error": type(exc).__name__ + ": " + str(exc)[:180]}


def extract_refs(url, body, content_type):
    text = body.decode("utf-8", "replace")
    refs = []
    if "html" in content_type.lower() or re.search(r"<\s*(a|link|script|form|img)\b", text, re.I):
        parser = RefParser()
        try:
            parser.feed(text)
            refs.extend(parser.refs)
        except Exception:
            pass
    if "css" in content_type.lower() or urlsplit_path(url).lower().endswith(".css"):
        refs.extend(re.findall(r"url\(\s*['\"]?([^\s)'\"]+)", text, re.I))
        refs.extend(re.findall(r"@import\s+['\"]([^'\"]+)", text, re.I))
    if "xml" in content_type.lower() or urlsplit_path(url).lower().endswith((".xml", ".txt")):
        refs.extend(re.findall(r"<loc>\s*([^<]+)\s*</loc>", text, re.I))
    resolved = []
    for ref in refs:
        ref = ref.strip()
        if not ref or ref.startswith(("#", "javascript:", "mailto:", "data:")):
            continue
        absolute = urllib.parse.urljoin(url, ref)
        if is_same_origin(absolute):
            p = urllib.parse.urlsplit(absolute)
            resolved.append(urllib.parse.urlunsplit(("http", HOST + (":80" if PORT != 80 else ""), p.path or "/", p.query, "")))
    return text, list(dict.fromkeys(resolved))


def urlsplit_path(url):
    return urllib.parse.urlsplit(url).path


def main():
    seeds = ["/", "/index.php", "/index.php?page=page1.php",
             "/index.php?page=page2.php", "/index.php?page=page3.php",
             "/css/style.css", "/robots.txt", "/sitemap.xml"]
    queue = [(urllib.parse.urljoin(BASE, p), "seed") for p in seeds]
    seen = set()
    results = []
    while queue:
        url, source = queue.pop(0)
        if url in seen:
            continue
        seen.add(url)
        if not is_same_origin(url):
            continue
        obs = request(url)
        ctype = obs["headers"].get("Content-Type", "")
        text, refs = extract_refs(url, obs["body"], ctype)
        # One-hop discovery: fetch references exposed by seed responses, but do not crawl recursively.
        if source == "seed":
            for ref in refs:
                if ref not in seen and all(ref != q[0] for q in queue):
                    queue.append((ref, "discovered"))
        low = text.lower()
        relevant = []
        for term in ("flag", "include", "page=", "file", "path", "error", "not found", "warning"):
            pos = low.find(term)
            if pos >= 0:
                excerpt = re.sub(r"\s+", " ", text[max(0, pos - 65):pos + 155]).strip()
                relevant.append({"term": term, "excerpt": excerpt[:220]})
        flag_like = bool(re.search(r"(?:flag|ctf)\{[^}]{1,200}\}", text, re.I))
        results.append({
            "url": url, "source": source, "status": obs["status"],
            "error": obs["error"], "final_url": obs["final_url"],
            "content_type": ctype, "body_bytes": len(obs["body"]),
            "body_truncated": obs["truncated"],
            "same_origin_references": refs[:30],
            "reference_list_truncated": len(refs) > 30,
            "flag_pattern_observed": flag_like,
            "relevant_excerpts": relevant[:5]
        })
    print(json.dumps({"target": BASE, "method": "GET", "request_count": len(results),
                      "crawl_policy": "Known resources plus one hop of same-origin references; no recursive crawl.",
                      "results": results}, ensure_ascii=False))

if __name__ == "__main__":
    main()

