import json
import re

import framework_evidence

BASE = "http://192.168.2.2:80"
PATHS = [
    "/.git/HEAD", "/.git/config", "/.git/index",
    "/.env", "/.env.backup",
    "/index.php", "/index.php~", "/index.php.bak", "/index.php.save", "/index.phps",
    "/config.php", "/config.php~", "/config.php.bak", "/config.php.save",
    "/db.php", "/database.php",
    "/backup.zip", "/backup.tar.gz", "/site.zip",
    "/composer.json", "/package.json", "/.DS_Store",
    "/robots.txt", "/sitemap.xml",
    "/page1.php", "/page2.php", "/page3.php",
]
MARKER = b"\n__HTTP_STATUS__:"


def envelope_fields(result):
    if isinstance(result, str):
        try:
            result = json.loads(result)
        except Exception:
            return {"envelope_text": result}
    if not isinstance(result, dict):
        return {"envelope_value": repr(result)}
    return result


records = []
for path in PATHS:
    url = BASE + path
    try:
        result = envelope_fields(framework_evidence.run_tool([
            "curl", "--silent", "--show-error", "--max-time", "6",
            "--output", "-", "--write-out", "\\n__HTTP_STATUS__:%{http_code}", url,
        ]))
        stdout_value = result.get("stdout", "")
        if isinstance(stdout_value, bytes):
            raw = stdout_value
        else:
            raw = str(stdout_value).encode("utf-8", "replace")
        status = None
        body = raw
        match = re.search(rb"\n__HTTP_STATUS__:(\d{3})\s*$", raw)
        if match:
            status = int(match.group(1))
            body = raw[:match.start()]
        record = {
            "path": path,
            "tool_status": result.get("status"),
            "exit_code": result.get("exit_code"),
            "http_status": status,
            "response_bytes": len(body),
            "response_sha256": hashlib.sha256(body).hexdigest(),
            "stderr": result.get("stderr", ""),
        }
        text = body.decode("utf-8", "replace")
        interesting = bool(re.search(
            r"flag|config|database|password|secret|credential|source|git|include|require",
            text, re.IGNORECASE,
        ))
        if status is not None and 200 <= status < 300:
            record["excerpt"] = text[:240].replace("\r", "\\r").replace("\n", "\\n")
        if status is not None and 200 <= status < 300 and interesting:
            record["relevant_body_complete"] = text
        records.append(record)
    except Exception as exc:
        records.append({"path": path, "request_error": type(exc).__name__ + ": " + str(exc)})

print(json.dumps({
    "target": BASE,
    "method": "GET",
    "purpose": "Public deployment artifact and source/configuration path checks; no traversal or PHP stream payloads",
    "requests": records,
}, ensure_ascii=False, separators=(",", ":")))

