import json
import re

from framework_evidence import run_tool

BASE = "http://192.168.2.2:80"
PATHS = [
    "/.git/HEAD", "/.git/config", "/.git/index",
    "/.env", "/.env.backup",
    "/index.php", "/index.php~", "/index.php.bak", "/index.php.save", "/index.phps",
    "/config.php", "/config.php~", "/config.php.bak", "/config.php.save",
    "/db.php", "/database.php",
    "/backup.zip", "/backup.tar.gz", "/site.zip",
    "/composer.json", "/package.json", "/.DS_Store",
    "/robots.txt", "/sitemap.xml",
    "/page1.php", "/page2.php", "/page3.php",
]
MARKER = "__CURL_META__"


def find_stdout(value):
    if isinstance(value, dict):
        candidate = value.get("stdout")
        if isinstance(candidate, str):
            return candidate
        for child in value.values():
            found = find_stdout(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_stdout(child)
            if found is not None:
                return found
    return None


def find_exit_code(value):
    if isinstance(value, dict):
        if "exit_code" in value:
            return value.get("exit_code")
        for child in value.values():
            found = find_exit_code(child)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_exit_code(child)
            if found is not None:
                return found
    return None


for path in PATHS:
    url = BASE + path
    argv = [
        "curl", "--silent", "--show-error", "--include", "--max-time", "20",
        "--write-out", "\\n" + MARKER + "%{http_code}\\t%{size_download}\\t%{errormsg}\\n",
        url,
    ]
    try:
        envelope = run_tool(argv)
        raw_stdout = find_stdout(envelope) or ""
        exit_code = find_exit_code(envelope)
        meta_match = re.search(r"__CURL_META__(\\d{3})\\t(\\d+)\\t([^\\r\\n]*)", raw_stdout)
        http_status = int(meta_match.group(1)) if meta_match else None
        downloaded = int(meta_match.group(2)) if meta_match else None
        curl_error = meta_match.group(3).strip() if meta_match else None
        before_meta = raw_stdout.split(MARKER, 1)[0]
        body = ""
        if "\\r\\n\\r\\n" in before_meta:
            body = before_meta.split("\\r\\n\\r\\n", 1)[1]
        elif "\\n\\n" in before_meta:
            body = before_meta.split("\\n\\n", 1)[1]
        successful = http_status is not None and 200 <= http_status < 300
        complete = exit_code == 0 and meta_match is not None
        record = {
            "requested_path": path,
            "url": url,
            "http_status": http_status,
            "curl_exit_code": exit_code,
            "transfer_outcome": "completed" if exit_code == 0 else "failed_or_unknown",
            "response_bytes_downloaded": downloaded,
            "response_completeness": "transfer_completed" if complete else "incomplete_or_unconfirmed",
            "curl_error": curl_error,
            "successful_response_excerpt": body[:500] if successful else None,
            "tool_envelope": envelope,
        }
        print(json.dumps(record, ensure_ascii=False))
    except Exception as exc:
        print(json.dumps({
            "requested_path": path,
            "url": url,
            "http_status": None,
            "transfer_outcome": "helper_or_execution_error",
            "response_completeness": "unknown",
            "error": repr(exc),
        }, ensure_ascii=False))

