import tempfile
from html.parser import HTMLParser

from framework_evidence import run_tool

BASE = "http://192.168.2.2:80"
PATHS = [
    "/.git/HEAD", "/.git/config", "/.git/index",
    "/.env", "/.env.backup",
    "/index.php", "/index.php~", "/index.php.bak", "/index.php.save", "/index.phps",
    "/config.php", "/config.php~", "/config.php.bak", "/config.php.save",
    "/db.php", "/database.php",
    "/backup.zip", "/backup.tar.gz", "/site.zip",
    "/composer.json", "/package.json", "/.DS_Store",
    "/robots.txt", "/sitemap.xml",
    "/page1.php", "/page2.php", "/page3.php",
    "/flag.txt",
]
MARKER = "__CURL_META__"


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.hidden_depth = 0

    def handle_starttag(self, tag, attrs):
        if tag.lower() in ("script", "style"):
            self.hidden_depth += 1

    def handle_endtag(self, tag):
        if tag.lower() in ("script", "style") and self.hidden_depth:
            self.hidden_depth -= 1

    def handle_data(self, data):
        if not self.hidden_depth:
            self.parts.append(data)


def tool_run(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list) and runs and isinstance(runs[0], dict):
            return runs[0]
        return envelope
    return {}


def excerpt_for(body):
    text = body.decode("utf-8", "replace")
    parser = TextExtractor()
    try:
        parser.feed(text)
        text = " ".join(parser.parts)
    except Exception:
        pass
    text = re.sub(r"\s+", " ", text).strip()
    return text[:280]


def main():
    body_dir = tempfile.mkdtemp(prefix="artifact_responses_")
    records = []
    for index, path in enumerate(PATHS):
        body_path = os.path.join(body_dir, "%02d.body" % index)
        url = BASE + path
        fmt = "\\n" + MARKER + "%{http_code}\\t%{size_download}\\t%{content_type}\\t%{url_effective}\\n"
        argv = [
            "curl", "--silent", "--show-error",
            "--connect-timeout", "4", "--max-time", "15",
            "--output", body_path, "--write-out", fmt, url,
        ]
        record = {"path": path, "url": url}
        try:
            envelope = run_tool(argv)
            result = tool_run(envelope)
            stdout = result.get("stdout", "")
            stderr = result.get("stderr", "")
            exit_code = result.get("exit_code")
            if not isinstance(stdout, str):
                stdout = str(stdout)
            if not isinstance(stderr, str):
                stderr = str(stderr)
            metadata = stdout.rsplit(MARKER, 1)
            status = None
            reported_bytes = None
            content_type = None
            effective_url = None
            parse_error = None
            if len(metadata) == 2:
                fields = metadata[1].strip().split("\t", 3)
                if len(fields) == 4:
                    try:
                        status = int(fields[0])
                    except ValueError:
                        pass
                    try:
                        reported_bytes = int(fields[1])
                    except ValueError:
                        pass
                    content_type, effective_url = fields[2], fields[3]
                else:
                    parse_error = "curl write-out metadata had an unexpected format"
            else:
                parse_error = "curl write-out metadata was absent"

            body = b""
            body_exists = os.path.isfile(body_path)
            if body_exists:
                with open(body_path, "rb") as response_file:
                    body = response_file.read()
            complete = exit_code == 0
            record.update({
                "http_status": status,
                "transfer_outcome": "complete" if complete else "incomplete_or_failed",
                "curl_exit_code": exit_code,
                "response_complete": complete,
                "response_bytes": len(body),
                "curl_reported_bytes": reported_bytes,
                "content_type": content_type,
                "effective_url": effective_url,
                "body_file": body_path if body_exists else None,
                "stderr": stderr.strip()[:500],
            })
            if parse_error:
                record["metadata_limitation"] = parse_error
            if status is not None and 200 <= status < 300:
                record["excerpt"] = excerpt_for(body)
        except Exception as exc:
            record.update({
                "http_status": None,
                "transfer_outcome": "not_obtained",
                "response_complete": False,
                "body_file": body_path if os.path.isfile(body_path) else None,
                "error": "%s: %s" % (type(exc).__name__, exc),
            })
        records.append(record)

    print(json.dumps({
        "target": BASE,
        "method": "GET via curl; redirects are not followed",
        "body_directory": body_dir,
        "results": records,
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

