import json
import re
import sys

import framework_evidence

BASE = "http://192.168.2.2:80"
# These are the paths explicitly identifiable in the supplied partial response
# evidence. Do not infer additional entries from omitted evidence.
PATHS = [
    "/.git/HEAD",
    "/.git/config",
    "/.git/index",
    "/.env",
    "/.env.backup",
    "/page2.php",
    "/page3.php",
    "/flag.txt",
]


def as_text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if value is None:
        return ""
    return str(value)


def get_exit_code(envelope):
    if not isinstance(envelope, dict):
        return None
    value = envelope.get("exit_code")
    if value is None and isinstance(envelope.get("result"), dict):
        value = envelope["result"].get("exit_code")
    try:
        return int(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def main():
    for path in PATHS:
        url = BASE + path
        argv = [
            "wget", "--server-response", "--output-document=-",
            "--tries=1", "--timeout=10", "--max-redirect=0", url,
        ]
        try:
            envelope = framework_evidence.run_tool(argv)
        except Exception as exc:
            print(json.dumps({
                "requested_path": path,
                "url": url,
                "tool_invocation_error": repr(exc),
                "http_status": None,
                "transfer_outcome": "helper invocation failed",
                "response_complete": None,
                "excerpt": None,
            }, ensure_ascii=False))
            continue

        if not isinstance(envelope, dict):
            envelope = {"returned_value": envelope}
        stdout = as_text(envelope.get("stdout"))
        stderr = as_text(envelope.get("stderr"))
        exit_code = get_exit_code(envelope)

        # wget writes server response headers to stderr. Preserve the raw streams
        # below, while extracting the final status line for a compact assessment.
        status_matches = re.findall(
            r"HTTP/\S+\s+(\d{3})(?:\s+[^\r\n]*)?", stderr, flags=re.IGNORECASE
        )
        status = int(status_matches[-1]) if status_matches else None
        lengths = re.findall(r"(?im)^\s*Content-Length:\s*(\d+)\s*$", stderr)
        expected_length = int(lengths[-1]) if lengths else None
        body_bytes = len(stdout.encode("utf-8", errors="replace"))

        if exit_code == 0:
            transfer_outcome = "wget completed successfully"
        elif exit_code == 8 and status is not None:
            transfer_outcome = "HTTP server returned an error status; wget exit 8"
        else:
            transfer_outcome = "wget did not report successful completion"

        if expected_length is not None:
            complete = body_bytes == expected_length
        elif exit_code == 0 and status is not None:
            # Successful wget completion without a Content-Length is evidence of
            # completion, but not an independently length-verified response.
            complete = "wget-reported-complete; length-unverified"
        else:
            complete = None

        excerpt = None
        if status is not None and 200 <= status < 300:
            excerpt = " ".join(stdout.split())[:240]

        print(json.dumps({
            "requested_path": path,
            "url": url,
            "http_status": status,
            "transfer_outcome": transfer_outcome,
            "wget_exit_code": exit_code,
            "response_complete": complete,
            "response_bytes_from_stdout": body_bytes,
            "content_length_header": expected_length,
            "excerpt_for_successful_response": excerpt,
            "raw_tool_envelope": envelope,
        }, ensure_ascii=False))

    print(json.dumps({
        "coverage_note": (
            "The supplied prior-response preview was truncated. This check covers only "
            "the eight paths explicitly visible in that preview; unshown paths from the "
            "earlier list were not guessed or checked."
        )
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

