import ast
import json
import os
import re
import tempfile
from pathlib import Path

import framework_evidence

TARGET = "http://192.168.2.2:80"
PRIOR_SCRIPT = Path("/root/scripts/verify_artifact_responses.py")
VISIBLE_PATHS = [
    "/.git/HEAD",
    "/.git/config",
    "/.git/index",
    "/.env",
    "/.env.backup",
    "/page2.php",
    "/page3.php",
    "/flag.txt",
]


def recover_paths():
    candidates = []
    source_note = ""
    try:
        source = PRIOR_SCRIPT.read_text(encoding="utf-8")
        tree = ast.parse(source, filename=str(PRIOR_SCRIPT))
        for node in ast.walk(tree):
            if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
                values = []
                for item in node.elts:
                    if isinstance(item, ast.Constant) and isinstance(item.value, str):
                        value = item.value
                        if value.startswith("/") and not value.startswith("//"):
                            values.append(value)
                if values:
                    candidates.append(values)
        source_note = "Recovered literal path candidates from the prior generated check script."
    except Exception as exc:
        source_note = "Could not recover paths from prior generated script: {}: {}".format(
            type(exc).__name__, exc
        )
    recovered = max(candidates, key=len) if candidates else []
    # The visible evidence independently establishes these as previously checked paths.
    ordered = []
    for path in recovered + VISIBLE_PATHS:
        if path not in ordered:
            ordered.append(path)
    if len(recovered) <= len(VISIBLE_PATHS):
        source_note += " The complete earlier path list is not established by the available source; visible paths are checked, and omitted paths remain unknown."
    return ordered, source_note


def get_field(envelope, name):
    if isinstance(envelope, dict):
        if name in envelope:
            return envelope[name]
        for key in ("result", "tool_run", "observation"):
            nested = envelope.get(key)
            if isinstance(nested, dict) and name in nested:
                return nested[name]
    return None


paths, coverage_note = recover_paths()
results = []
for index, path in enumerate(paths):
    url = TARGET + path
    fd, body_path = tempfile.mkstemp(prefix="wget_artifact_{}_".format(index), suffix=".body")
    os.close(fd)
    argv = ["wget", "--server-response", "--no-verbose", "-O", body_path, url]
    try:
        envelope = framework_evidence.run_tool(argv)
        if not isinstance(envelope, dict):
            envelope = {"returned_value": envelope}
        raw_stderr = get_field(envelope, "stderr")
        if not isinstance(raw_stderr, str):
            raw_stderr = ""
        statuses = re.findall(r"HTTP/\S+\s+(\d{3})\b", raw_stderr, re.IGNORECASE)
        status = int(statuses[-1]) if statuses else None
        exit_code = get_field(envelope, "exit_code")
        try:
            body = Path(body_path).read_bytes()
        except OSError:
            body = b""
        transfer_ok = exit_code == 0
        # A zero wget exit and a captured final HTTP response indicate a completed
        # transfer; absence of either leaves completeness unknown.
        complete = bool(transfer_ok and status is not None)
        excerpt = ""
        if status is not None and 200 <= status < 300:
            excerpt = body[:240].decode("utf-8", errors="replace").replace("\r", " ").replace("\n", " ")
        results.append({
            "requested_path": path,
            "url": url,
            "http_status": status,
            "transfer_outcome": "complete" if transfer_ok else "failed_or_unknown",
            "response_complete": complete,
            "response_bytes_saved": len(body),
            "successful_response_excerpt": excerpt,
            "tool_envelope": envelope,
        })
    except Exception as exc:
        results.append({
            "requested_path": path,
            "url": url,
            "http_status": None,
            "transfer_outcome": "error",
            "response_complete": False,
            "error": "{}: {}".format(type(exc).__name__, exc),
        })
    finally:
        try:
            os.unlink(body_path)
        except OSError:
            pass

print(json.dumps({
    "target": TARGET,
    "method": "wget GET per path",
    "path_recovery_note": coverage_note,
    "results": results,
}, ensure_ascii=False))

