import ast
import json
import sys
import urllib.error
import urllib.request
from pathlib import Path

SCRIPT_PATH = Path("/root/scripts/wget_artifact_response_check.py")
BASE_URL = "http://192.168.2.2:80"


def recover_paths(source):
    tree = ast.parse(source, filename=str(SCRIPT_PATH))
    candidates = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.List, ast.Tuple)):
            values = []
            valid = True
            for item in node.elts:
                if not isinstance(item, ast.Constant) or not isinstance(item.value, str) or not item.value.startswith("/"):
                    valid = False
                    break
                values.append(item.value)
            if valid and values:
                candidates.append(values)
    if not candidates:
        raise ValueError("No literal absolute-path candidate list found in generated check script")
    paths = max(candidates, key=len)
    # Preserve candidate order and remove only exact duplicates.
    return list(dict.fromkeys(paths))


class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def check_path(opener, path):
    result = {
        "path": path,
        "http_status": None,
        "transfer_outcome": "failed",
        "response_complete": None,
        "excerpt": "",
    }
    request = urllib.request.Request(BASE_URL + path, method="GET")
    response = None
    try:
        try:
            response = opener.open(request, timeout=10)
        except urllib.error.HTTPError as exc:
            # HTTP error statuses are still attributable HTTP responses; read their bodies.
            response = exc
        result["http_status"] = response.getcode()
        body = response.read()
        result["transfer_outcome"] = "completed"
        content_length = response.headers.get("Content-Length")
        if content_length is not None:
            try:
                result["response_complete"] = len(body) == int(content_length)
            except ValueError:
                result["response_complete"] = None
        else:
            # A clean read to EOF completed the response body; no declared length to compare.
            result["response_complete"] = True
        if 200 <= result["http_status"] < 300:
            excerpt = body.decode("utf-8", errors="replace")
            excerpt = " ".join(excerpt.split())
            result["excerpt"] = excerpt[:240]
    except Exception as exc:
        result["transfer_outcome"] = "failed: " + type(exc).__name__ + ": " + str(exc)[:160]
    finally:
        if response is not None:
            response.close()
    return result


def main():
    try:
        source = SCRIPT_PATH.read_text(encoding="utf-8")
        paths = recover_paths(source)
    except Exception as exc:
        print(json.dumps({"error": "candidate_path_recovery_failed", "detail": str(exc)}, ensure_ascii=False))
        return 1

    opener = urllib.request.build_opener(NoRedirectHandler())
    results = [check_path(opener, path) for path in paths]
    print(json.dumps(results, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())

