import ast
import json
import os
import re
import sys

SCRIPT_PATH = "/root/scripts/wget_artifact_response_check.py"
BASE_URL = "http://192.168.2.2:80"
META_MARKER = "\n__EVIDENCE_META__"


def path_literal(node):
    return (
        isinstance(node, ast.Constant)
        and isinstance(node.value, str)
        and node.value.startswith("/")
        and not node.value.startswith("//")
        and not any(ch.isspace() for ch in node.value)
    )


def recover_paths(source):
    tree = ast.parse(source, filename=SCRIPT_PATH)
    candidates = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.List, ast.Tuple)) and node.elts and all(path_literal(e) for e in node.elts):
            values = [e.value for e in node.elts]
            if len(values) == len(set(values)):
                candidates.append(values)
    if not candidates:
        raise ValueError("No literal candidate-path list found in generated check script")
    longest = max(map(len, candidates))
    winners = [paths for paths in candidates if len(paths) == longest]
    distinct = {tuple(paths) for paths in winners}
    if len(distinct) != 1:
        raise ValueError("Ambiguous candidate-path lists of equal maximum length in generated check script")
    return list(next(iter(distinct)))


def as_envelope(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return {"raw_return": value}
    return value


def extract_run(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list) and runs:
            return runs[0]
    return {}


def parse_response(run):
    stdout = run.get("stdout", "")
    if not isinstance(stdout, str):
        stdout = str(stdout)
    response, meta = stdout, ""
    if META_MARKER in stdout:
        response, meta = stdout.rsplit(META_MARKER, 1)
    status = None
    downloaded = None
    match = re.search(r"(\d{3})\|([0-9]+(?:\.[0-9]+)?)", meta)
    if match:
        status = int(match.group(1))
        try:
            downloaded = int(float(match.group(2)))
        except ValueError:
            pass
    header_end = response.find("\r\n\r\n")
    separator_len = 4
    if header_end < 0:
        header_end = response.find("\n\n")
        separator_len = 2
    headers = response[:header_end] if header_end >= 0 else ""
    body = response[header_end + separator_len:] if header_end >= 0 else ""
    declared = None
    for line in headers.splitlines():
        if line.lower().startswith("content-length:"):
            try:
                declared = int(line.split(":", 1)[1].strip())
            except ValueError:
                pass
    exit_code = run.get("exit_code")
    complete = exit_code == 0 and (declared is None or downloaded is None or declared == downloaded)
    excerpt = ""
    if status is not None and 200 <= status < 300:
        excerpt = " ".join(body.split())[:240]
    return status, downloaded, declared, complete, excerpt


def main():
    if not os.path.isfile(SCRIPT_PATH):
        print(json.dumps({"error": "generated wget check script is unavailable", "source_path": SCRIPT_PATH}, ensure_ascii=False))
        return 2
    try:
        with open(SCRIPT_PATH, "r", encoding="utf-8") as source_file:
            paths = recover_paths(source_file.read())
    except Exception as exc:
        print(json.dumps({"error": "could not recover exact candidate path list", "source_path": SCRIPT_PATH, "detail": str(exc)}, ensure_ascii=False))
        return 2

    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"error": "framework_evidence helper could not be imported", "detail": str(exc), "recovered_path_count": len(paths)}, ensure_ascii=False))
        return 2

    results = []
    for path in paths:
        url = BASE_URL + path
        argv = [
            "curl", "--silent", "--show-error", "--include",
            "--connect-timeout", "5", "--max-time", "10",
            "--write-out", "\n__EVIDENCE_META__%{http_code}|%{size_download}\n",
            "--url", url,
        ]
        try:
            envelope = as_envelope(run_tool(argv))
            run = extract_run(envelope)
            status, downloaded, declared, complete, excerpt = parse_response(run)
            exit_code = run.get("exit_code")
            outcome = "completed" if exit_code == 0 else "failed_or_incomplete"
            results.append({
                "path": path,
                "http_status": status,
                "transfer_outcome": outcome,
                "response_complete": complete,
                "successful_response_excerpt": excerpt,
                "response_bytes": downloaded,
                "content_length": declared,
                "tool_envelope": envelope,
            })
        except Exception as exc:
            results.append({
                "path": path,
                "http_status": None,
                "transfer_outcome": "tool_error",
                "response_complete": False,
                "successful_response_excerpt": "",
                "error": str(exc),
            })

    print(json.dumps({
        "target": BASE_URL,
        "client": "curl",
        "path_list_source": SCRIPT_PATH,
        "recovered_path_count": len(paths),
        "checked_path_count": len(results),
        "results": results,
    }, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

