import ast
import json
import os
import urllib.error
import urllib.request

SCRIPT_PATH = "/root/scripts/wget_artifact_response_check.py"
BASE_URL = "http://192.168.2.2:80"


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def recover_paths(source):
    tree = ast.parse(source, filename=SCRIPT_PATH)
    candidates = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.Assign, ast.AnnAssign)):
            continue
        value = node.value
        if not isinstance(value, (ast.List, ast.Tuple)):
            continue
        try:
            items = ast.literal_eval(value)
        except (ValueError, TypeError, SyntaxError):
            continue
        if not isinstance(items, (list, tuple)) or not items:
            continue
        if not all(isinstance(item, str) and item.startswith("/") for item in items):
            continue
        if isinstance(node, ast.Assign):
            names = [t.id.lower() for t in node.targets if isinstance(t, ast.Name)]
        else:
            names = [node.target.id.lower()] if isinstance(node.target, ast.Name) else []
        score = max((2 if "candidate" in name else 1 if "path" in name else 0
                     for name in names), default=0)
        candidates.append((len(items), score, list(items)))
    if not candidates:
        raise ValueError("No literal absolute-path list found in generated checker")
    best_key = max((length, score) for length, score, _ in candidates)
    winners = [paths for length, score, paths in candidates
               if (length, score) == best_key]
    unique = {tuple(paths) for paths in winners}
    if len(unique) != 1:
        raise ValueError("Candidate path list is ambiguous in generated checker")
    paths = list(next(iter(unique)))
    if len(set(paths)) != len(paths):
        raise ValueError("Recovered candidate path list contains duplicates")
    return paths


def fetch(opener, path):
    record = {
        "path": path,
        "http_status": None,
        "transfer_outcome": "not_started",
        "response_complete": False,
        "excerpt": "",
    }
    # Preserve the recovered path while ensuring the request remains on the target host.
    if not path.startswith("/") or path.startswith("//"):
        record["transfer_outcome"] = "rejected_invalid_path"
        return record
    request = urllib.request.Request(BASE_URL + path, method="GET")
    response = None
    try:
        try:
            response = opener.open(request, timeout=12)
        except urllib.error.HTTPError as exc:
            response = exc
        record["http_status"] = response.getcode()
        headers = response.headers
        expected_length = headers.get("Content-Length")
        try:
            expected_length = int(expected_length) if expected_length is not None else None
        except (TypeError, ValueError):
            expected_length = None
        body = response.read()
        record["response_complete"] = (
            expected_length is None or len(body) == expected_length
        )
        record["transfer_outcome"] = (
            "completed" if record["response_complete"] else
            "incomplete_content_length_mismatch"
        )
        if 200 <= record["http_status"] < 300:
            text = body.decode("utf-8", errors="replace")
            text = " ".join(text.split())
            record["excerpt"] = text[:180]
    except Exception as exc:
        record["transfer_outcome"] = "error: " + type(exc).__name__ + ": " + str(exc)
    finally:
        if response is not None:
            try:
                response.close()
            except Exception:
                pass
    return record


def main():
    try:
        with open(SCRIPT_PATH, "r", encoding="utf-8") as handle:
            source = handle.read()
        paths = recover_paths(source)
    except Exception as exc:
        print(json.dumps({"error": type(exc).__name__ + ": " + str(exc)},
                         separators=(",", ":")))
        return
    opener = urllib.request.build_opener(NoRedirect())
    results = [fetch(opener, path) for path in paths]
    print(json.dumps(results, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    main()

