import ast
import json
import socket
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import urlsplit
from urllib.request import Request, urlopen

SCRIPT = Path("/root/scripts/wget_artifact_response_check.py")
BASE = "http://192.168.2.2:80"
TIMEOUT = 8


def recover_paths(source):
    tree = ast.parse(source, filename=str(SCRIPT))
    candidates = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.Assign, ast.AnnAssign)):
            continue
        value = node.value
        if not isinstance(value, (ast.List, ast.Tuple)) or not value.elts:
            continue
        try:
            values = [ast.literal_eval(item) for item in value.elts]
        except (ValueError, TypeError):
            continue
        if not all(isinstance(item, str) and item.startswith("/") for item in values):
            continue
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        names = [getattr(target, "id", "") for target in targets]
        candidates.append((len(values), any("path" in name.lower() or "candidate" in name.lower() for name in names), names, values))
    if not candidates:
        raise ValueError("No literal list of slash-prefixed candidate paths found in the generated script")
    largest = max(item[0] for item in candidates)
    best = [item for item in candidates if item[0] == largest]
    preferred = [item for item in best if item[1]]
    if preferred:
        best = preferred
    distinct = {tuple(item[3]) for item in best}
    if len(distinct) != 1:
        raise ValueError("Multiple equally large candidate path lists are ambiguous; no requests made")
    chosen = best[0]
    # Preserve the source list exactly, including order and duplicates.
    return chosen[3], chosen[2]


def request_path(path):
    if not isinstance(path, str) or not path.startswith("/"):
        return {"path": path, "http_status": None, "transfer_outcome": "not_requested_invalid_path", "response_complete": False, "excerpt": ""}
    url = BASE + path
    parts = urlsplit(url)
    if parts.scheme != "http" or parts.hostname != "192.168.2.2" or parts.port != 80:
        return {"path": path, "http_status": None, "transfer_outcome": "not_requested_out_of_scope_url", "response_complete": False, "excerpt": ""}

    response = None
    status = None
    try:
        try:
            response = urlopen(Request(url, headers={"User-Agent": "Python-urllib artifact recheck"}), timeout=TIMEOUT)
        except HTTPError as exc:
            response = exc
        status = response.getcode()
        body = response.read()
        declared = response.headers.get("Content-Length")
        complete = declared is None or len(body) == int(declared)
        outcome = "completed" if complete else "incomplete_content_length_mismatch"
        excerpt = ""
        if status is not None and 200 <= status < 300:
            charset = response.headers.get_content_charset() or "utf-8"
            text = body.decode(charset, errors="replace")
            excerpt = " ".join(text.split())[:180]
        return {"path": path, "http_status": status, "transfer_outcome": outcome, "response_complete": complete, "excerpt": excerpt}
    except (URLError, OSError, socket.timeout, ValueError) as exc:
        detail = getattr(exc, "reason", exc)
        return {"path": path, "http_status": status, "transfer_outcome": "error: " + str(detail)[:160], "response_complete": False, "excerpt": ""}
    finally:
        if response is not None:
            response.close()


def main():
    try:
        source = SCRIPT.read_text(encoding="utf-8")
        paths, names = recover_paths(source)
    except Exception as exc:
        print(json.dumps({"target": BASE, "path_source": str(SCRIPT), "path_recovery_complete": False, "error": str(exc), "results": []}, separators=(",", ":")))
        return

    results = [request_path(path) for path in paths]
    print(json.dumps({"target": BASE, "client": "Python standard-library urllib.request", "path_source": str(SCRIPT), "path_list_variable": names, "path_recovery_complete": True, "candidate_count": len(paths), "checked_count": len(results), "results": results}, separators=(",", ":")))


if __name__ == "__main__":
    main()

