import ast
import json
import os
import urllib.error
import urllib.request
from pathlib import Path

ROOT = Path('/root/scripts')
KNOWN_COMPLETE = {
    '/.git/HEAD', '/.git/config', '/.git/index', '/.env', '/.env.backup',
    '/page2.php', '/page3.php', '/flag.txt'
}
TARGET = 'http://192.168.2.2:80'
EXCERPT_CHARS = 240


def path_values(value):
    if not isinstance(value, (list, tuple, set)):
        return []
    found = []
    for item in value:
        if isinstance(item, str) and item.startswith('/') and not item.startswith('//'):
            found.append(item)
    return found


def inspect_python_file(path):
    try:
        source = path.read_text(encoding='utf-8', errors='replace')
    except OSError as exc:
        return [], {'path': str(path), 'error': str(exc)}
    try:
        tree = ast.parse(source, filename=str(path))
    except SyntaxError as exc:
        return [], {'path': str(path), 'parse_error': str(exc)}

    lists = []
    for node in ast.walk(tree):
        names = []
        value_node = None
        if isinstance(node, ast.Assign):
            names = [t.id for t in node.targets if isinstance(t, ast.Name)]
            value_node = node.value
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            names = [node.target.id]
            value_node = node.value
        if not value_node:
            continue
        try:
            value = ast.literal_eval(value_node)
        except (ValueError, TypeError, SyntaxError):
            continue
        paths = path_values(value)
        if paths:
            for name in names or ['<unnamed-list>']:
                lists.append({
                    'source': str(path),
                    'variable': name,
                    'paths': paths,
                    'path_count': len(paths),
                })
    return lists, None


def main():
    inspected = []
    lists = []
    errors = []
    if not ROOT.is_dir():
        print(json.dumps({
            'target': TARGET,
            'recovery': {'status': 'unavailable', 'reason': 'Generated scripts directory is not accessible', 'path': str(ROOT)},
            'known_complete_paths_skipped': sorted(KNOWN_COMPLETE),
            'results': []
        }, ensure_ascii=False))
        return

    try:
        files = sorted(p for p in ROOT.rglob('*') if p.is_file() and p.suffix.lower() == '.py'
                       and any(word in p.name.lower() for word in ('wget', 'artifact', 'response', 'check')))
    except OSError as exc:
        files = []
        errors.append({'path': str(ROOT), 'error': str(exc)})

    for path in files:
        found, error = inspect_python_file(path)
        inspected.append(str(path))
        lists.extend(found)
        if error:
            errors.append(error)

    # Prefer a literal list of the reported size, then the largest relevant
    # literal list. Keep its source and variable visible for auditability.
    ranked = sorted(
        lists,
        key=lambda entry: (entry['path_count'] == 28, entry['path_count'],
                          any(k in entry['variable'].lower() for k in ('candidate', 'path', 'url', 'visible', 'check'))),
        reverse=True
    )
    selected = ranked[0] if ranked else None
    candidates = []
    if selected:
        for item in selected['paths']:
            if item not in candidates:
                candidates.append(item)

    recovered_exact_28 = bool(selected and selected['path_count'] == 28 and len(candidates) == 28)
    recovery_status = 'complete_28_literal_list_recovered' if recovered_exact_28 else (
        'partial_literal_list_recovered' if candidates else 'candidate_list_not_recovered'
    )
    results = []
    for path in candidates:
        if path in KNOWN_COMPLETE:
            continue
        url = TARGET + path
        record = {
            'path': path,
            'requested_url': url,
            'http_status': None,
            'transfer_outcome': 'not_completed',
            'response_complete': False,
            'excerpt': ''
        }
        request = urllib.request.Request(url, headers={'User-Agent': 'candidate-list-recovery/1.0'}, method='GET')
        response = None
        try:
            try:
                response = urllib.request.urlopen(request, timeout=8)
            except urllib.error.HTTPError as exc:
                response = exc
            record['http_status'] = response.getcode()
            body = response.read()
            record['transfer_outcome'] = 'completed'
            record['response_complete'] = True
            excerpt = body.decode('utf-8', errors='replace').replace('\r', ' ').replace('\n', ' ')
            record['excerpt'] = ' '.join(excerpt.split())[:EXCERPT_CHARS]
            if response.geturl() != url:
                record['final_url'] = response.geturl()
        except Exception as exc:
            record['transfer_outcome'] = 'error'
            record['error'] = type(exc).__name__ + ': ' + str(exc)
        finally:
            if response is not None:
                try:
                    response.close()
                except Exception:
                    pass
        results.append(record)

    output = {
        'target': TARGET,
        'method': 'inspect generated Python source using AST literals; urllib GET for recovered candidates not covered by complete prior results',
        'prohibited_tests_repeated': False,
        'source_directory': str(ROOT),
        'inspected_python_files': inspected,
        'recovery': {
            'status': recovery_status,
            'reported_prior_check_count': 28,
            'selected_list_source': selected['source'] if selected else None,
            'selected_list_variable': selected['variable'] if selected else None,
            'selected_literal_path_count': selected['path_count'] if selected else 0,
            'unique_candidate_count': len(candidates),
            'exact_28_reconciled': recovered_exact_28,
            'candidate_lists_found': [
                {'source': item['source'], 'variable': item['variable'], 'path_count': item['path_count']}
                for item in ranked
            ],
            'recovery_errors': errors
        },
        'known_complete_paths_skipped': sorted(KNOWN_COMPLETE),
        'additional_candidates_checked': len(results),
        'results': results
    }
    print(json.dumps(output, ensure_ascii=False))


if __name__ == '__main__':
    main()

