import ast
import json
import os
import urllib.error
import urllib.request

BASE = "http://192.168.2.2:80"
SCRIPT_DIR = "/root/scripts"
SOURCES = [
    os.path.join(SCRIPT_DIR, "verify_artifact_responses.py"),
    os.path.join(SCRIPT_DIR, "wget_artifact_response_check.py"),
]
PREVIOUSLY_CHECKED = {
    "/.git/HEAD", "/.git/config", "/.git/index", "/.env",
    "/.env.backup", "/page2.php", "/page3.php", "/flag.txt",
}


def path_strings(value):
    if not isinstance(value, (list, tuple)):
        return None
    if not all(isinstance(item, str) and item.startswith("/") for item in value):
        return None
    return list(value)


def recover_from_source(path):
    with open(path, "r", encoding="utf-8", errors="replace") as source_file:
        source = source_file.read()
    tree = ast.parse(source, filename=path)
    values = {}
    candidates = []

    # Resolve simple literal assignments and lists assigned from earlier names.
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            targets = [t.id for t in node.targets if isinstance(t, ast.Name)]
            try:
                value = ast.literal_eval(node.value)
            except (ValueError, TypeError):
                value = values.get(node.value.id) if isinstance(node.value, ast.Name) else None
            for name in targets:
                values[name] = value
                paths = path_strings(value)
                if paths:
                    candidates.append((name, paths))
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            try:
                value = ast.literal_eval(node.value) if node.value is not None else None
            except (ValueError, TypeError):
                value = None
            values[node.target.id] = value
            paths = path_strings(value)
            if paths:
                candidates.append((node.target.id, paths))

    exact = [(name, paths) for name, paths in candidates if len(paths) == 28]
    if not exact:
        return None, "no literal 28-path list found"
    # Prefer candidate/path-named variables; otherwise use the first exact list.
    exact.sort(key=lambda item: (not any(k in item[0].lower() for k in ("candidate", "path", "url")), item[0]))
    name, paths = exact[0]
    return {"variable": name, "paths": paths}, None


def request_path(path):
    url = BASE + path
    request = urllib.request.Request(url, method="GET", headers={"User-Agent": "candidate-recheck/1.0"})
    response = None
    try:
        response = urllib.request.urlopen(request, timeout=10)
        status = response.getcode()
        body = response.read()
        return status, "completed", True, body
    except urllib.error.HTTPError as exc:
        try:
            body = exc.read()
            return exc.code, "completed", True, body
        except Exception as read_error:
            return exc.code, "body_read_error: " + str(read_error), False, b""
    except Exception as exc:
        return None, "request_error: " + str(exc), False, b""
    finally:
        if response is not None:
            response.close()


def excerpt(body):
    text = body.decode("utf-8", errors="replace")
    return " ".join(text.split())[:180]


def main():
    recovered = None
    attempted_sources = []
    recovery_errors = []
    for source_path in SOURCES:
        try:
            value, error = recover_from_source(source_path)
            attempted_sources.append(source_path)
            if value is not None:
                recovered = (source_path, value)
                break
            recovery_errors.append({"source": source_path, "detail": error})
        except Exception as exc:
            attempted_sources.append(source_path)
            recovery_errors.append({"source": source_path, "detail": str(exc)})

    if recovered is None:
        print(json.dumps({
            "target": BASE,
            "path_recovery_complete": False,
            "sources_examined": attempted_sources,
            "recovery_errors": recovery_errors,
            "requests_made": 0,
            "note": "No exact 28-path literal list was recovered; no candidates were requested.",
        }, separators=(",", ":")))
        return

    source_path, record = recovered
    all_paths = record["paths"]
    unique_paths = list(dict.fromkeys(all_paths))
    covered = [p for p in unique_paths if p in PREVIOUSLY_CHECKED]
    remaining = [p for p in unique_paths if p not in PREVIOUSLY_CHECKED]
    results = []
    for path in remaining:
        status, outcome, complete, body = request_path(path)
        item = {
            "path": path,
            "http_status": status,
            "transfer_outcome": outcome,
            "response_complete": complete,
            "response_bytes": len(body),
        }
        if status is not None and 200 <= status < 300 and body:
            item["excerpt"] = excerpt(body)
        results.append(item)

    print(json.dumps({
        "target": BASE,
        "path_source": source_path,
        "path_list_variable": record["variable"],
        "path_recovery_complete": True,
        "candidate_count_in_source": len(all_paths),
        "unique_candidate_count": len(unique_paths),
        "previously_checked_count_reconciled": len(covered),
        "previously_checked_paths_in_list": covered,
        "remaining_count": len(remaining),
        "requests_completed_or_attempted": len(results),
        "results": results,
        "recovery_errors_before_success": recovery_errors,
    }, separators=(",", ":")))


if __name__ == "__main__":
    main()

