import json

from framework_evidence import run_tool


BASE = "http://192.168.2.2:80"
ROUTES = [
    "/",
    "/index.php?page=page1.php",
    "/index.php?page=page2.php",
    "/index.php?page=page3.php",
]


def curl_args(method, route, form_data=False):
    args = [
        "curl",
        "--silent",
        "--show-error",
        "--include",
        "--connect-timeout",
        "3",
        "--max-time",
        "10",
    ]
    if method == "OPTIONS":
        args.extend(["--request", "OPTIONS"])
    elif method == "HEAD":
        args.append("--head")
    elif method == "POST":
        if form_data:
            args.extend(["--data-urlencode", "page=page1.php"])
        else:
            args.extend(["--request", "POST"])
    else:
        raise ValueError("unsupported method in this focused check")
    args.append(BASE + route)
    return args


checks = []
for route in ROUTES:
    checks.append(("OPTIONS", route, False))
checks.extend([
    ("HEAD", "/index.php?page=page1.php", False),
    ("POST", "/index.php?page=page1.php", False),
    ("POST", "/index.php", True),
])

for method, route, form_data in checks:
    argv = curl_args(method, route, form_data)
    try:
        envelope = run_tool(argv)
        print(json.dumps(envelope, ensure_ascii=False))
    except Exception as exc:
        print(json.dumps({
            "command": argv,
            "status": "execution_error",
            "error": str(exc),
        }, ensure_ascii=False))
